    // Baud tick outputs
    output logic                    baud_tick,        // 1x baud rate tick
    output logic                    oversample_tick,  // 16x oversample tick for RX
    output logic [BAUD_DIV_WIDTH-1:0] baud_div_out    // Current divider value
