# =============================================================================
# AXI UART Peripheral - Build Makefile
# =============================================================================
# Responsibility: Build entry point orchestrating lint and simulation flows
# Dependencies: scripts/lint.sh, scripts/run_sim.sh
# =============================================================================

# -----------------------------------------------------------------------------
# Tool Configuration
# -----------------------------------------------------------------------------
SIM_TOOL ?= xrun
LINT_TOOL ?= verilator
WAVE_DUMP ?= 1

# -----------------------------------------------------------------------------
# RTL Source Files
# -----------------------------------------------------------------------------
RTL_PKG := rtl/pkg/uart_pkg.sv
RTL_MODULES := rtl/modules/axi_lite_regs.sv \
               rtl/modules/baud_gen.sv \
               rtl/modules/fifo_sync.sv \
               rtl/modules/uart_rx.sv \
               rtl/modules/uart_tx.sv
RTL_TOP := rtl/axi_uart_top.sv
RTL_SOURCES := $(RTL_PKG) $(RTL_MODULES) $(RTL_TOP)

TB_SOURCES := tb/axi_uart_tb.sv

# -----------------------------------------------------------------------------
# Directories
# -----------------------------------------------------------------------------
BUILD_DIR := sim_build
WAVE_DIR := waves

# -----------------------------------------------------------------------------
