# =============================================================================
# AXI UART Peripheral - Build Makefile
# =============================================================================
# Responsibility: Build entry point orchestrating lint and simulation flows
# Dependencies: scripts/lint.sh, scripts/run_sim.sh
# =============================================================================

# -----------------------------------------------------------------------------
# Tool Configuration
# -----------------------------------------------------------------------------
SIM_TOOL ?= xrun
LINT_TOOL ?= verilator
WAVE_DUMP ?= 1

# -----------------------------------------------------------------------------
# RTL Source Files
# -----------------------------------------------------------------------------
RTL_PKG := rtl/pkg/uart_pkg.sv
RTL_MODULES := rtl/modules/axi_lite_regs.sv \
               rtl/modules/baud_gen.sv \
               rtl/modules/fifo_sync.sv \
               rtl/modules/uart_rx.sv \
               rtl/modules/uart_tx.sv
RTL_TOP := rtl/axi_uart_top.sv
RTL_SOURCES := $(RTL_PKG) $(RTL_MODULES) $(RTL_TOP)

TB_SOURCES := tb/axi_uart_tb.sv

# -----------------------------------------------------------------------------
# Directories
# -----------------------------------------------------------------------------
BUILD_DIR := sim_build
WAVE_DIR := waves

# -----------------------------------------------------------------------------
# Phony Targets
# -----------------------------------------------------------------------------
.PHONY: all lint sim clean help

# -----------------------------------------------------------------------------
# Default Target
# -----------------------------------------------------------------------------
all: lint sim

# -----------------------------------------------------------------------------
# Lint Target - Invoke lint script
# -----------------------------------------------------------------------------
lint:
	@echo "[BUILD] Running RTL lint checks..."
	@if [ ! -f scripts/lint.sh ]; then \
		echo "[ERROR] scripts/lint.sh not found"; \
		exit 1; \
	fi
	@bash scripts/lint.sh $(RTL_SOURCES) --tool $(LINT_TOOL)
	@echo "[BUILD] Lint checks passed"

# -----------------------------------------------------------------------------
# Simulation Target - Invoke simulation script
# -----------------------------------------------------------------------------
sim: $(BUILD_DIR)
	@echo "[BUILD] Running functional simulation..."
	@if [ ! -f scripts/run_sim.sh ]; then \
		echo "[ERROR] scripts/run_sim.sh not found"; \
		exit 1; \
	fi
	@bash scripts/run_sim.sh --sources "$(RTL_SOURCES)" --tb "$(TB_SOURCES)" --tool $(SIM_TOOL) --waves $(WAVE_DUMP)
	@echo "[BUILD] Simulation complete"

# -----------------------------------------------------------------------------
# Clean Target - Remove build artifacts
# -----------------------------------------------------------------------------
clean:
	@echo "[BUILD] Cleaning build artifacts..."
	@rm -rf $(BUILD_DIR) $(WAVE_DIR)
	@echo "[BUILD] Clean complete"

# -----------------------------------------------------------------------------
# Build Directory Creation
